            Node("zero_excess_unused", "zero excess unused", "Exact declaration: theorem zero_excess_unused (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (D N : ℕ) (hr : ∀ v, DegreeCapacity.degree G v = D) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = N) (T : Finset V) (M : Finset (V × V)) (hf : Feasible G T M) (hc : T.card + M.card = N) (c : Bool) : (unusedSide T M color c).card = 0 ∨ (D-1)*(D-2)+1 ≤ (unusedSide T M color c).card.", DescribeRole.Theorem),
            Node("objective_one_side_support", "objective one side support", "Exact declaration: theorem objective_one_side_support (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (D N : ℕ) (hr : ∀ v, DegreeCapacity.degree G v = D) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = N) (hN : N ≤ 2*((D-1)*(D-2))+1) (T : Finset V) (M : Finset (V × V)) (hf : Feasible G T M) (hc : T.card + M.card = N) : ∃ c : Bool, (∀ v ∈ T, color v = c) ∧ (∀ v, color v = c → v ∈ T ∪ endpoints M).", DescribeRole.Theorem),
            Node("coloring_representatives", "coloring representatives", "Exact declaration: theorem coloring_representatives {C : Type} [DecidableEq C] (c : V → Option C) (hc : IsSubQuorum G c) : ∃ T : Finset V, ∃ M : Finset (V × V), Feasible G T M ∧ T.card + M.card = (palette c Finset.univ).card ∧ (M = ∅ → ∀ v w, c v ≠ none → c w = c v → ¬ G.Adj v w).", DescribeRole.Theorem),
            Node("palette_le_omega", "palette le omega", "Exact declaration: theorem palette_le_omega {C : Type} [DecidableEq C] (c : V → Option C) (hc : IsSubQuorum G c) : (palette c Finset.univ).card ≤ Omega G.", DescribeRole.Theorem),
            Node("psiSq_le_omega", "psiSq le omega", "Exact declaration: theorem psiSq_le_omega : psiSq G ≤ Omega G.", DescribeRole.Theorem),
            Node("parameter_comparison", "parameter comparison", "Exact declaration: theorem parameter_comparison : beta G 2 ≤ psiSq G ∧ psiSq G ≤ Omega G.", DescribeRole.Theorem),
            Node("threshold_parameters", "threshold parameters", "Exact declaration: theorem threshold_parameters (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (D N : ℕ) (hD : 3 ≤ D) (hr : ∀ v, DegreeCapacity.degree G v = D) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = N) (hN : N ≤ 2 * (D - 1) * (D - 2) + 4) : beta G 2 = N ∧ psiSq G = N ∧ Omega G = N.", DescribeRole.Theorem),
            Node("plane_parameter_specialization", "plane parameter specialization", "Exact declaration: theorem plane_parameter_specialization (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (q : ℕ) (hq : 2 ≤ q) (hr : ∀ v, DegreeCapacity.degree G v = q + 1) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = q*q+q+1) : beta G 2 = q*q+q+1 ∧ psiSq G = q*q+q+1 ∧ Omega G = q*q+q+1.", DescribeRole.Theorem),
            Node("plane_optimal_support", "plane optimal support", "Exact declaration: theorem plane_optimal_support (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (q : ℕ) (hq : 3 ≤ q) (hr : ∀ v, DegreeCapacity.degree G v = q+1) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = q*q+q+1) (T : Finset V) (M : Finset (V × V)) (hf : Feasible G T M) (hc : T.card+M.card = q*q+q+1) : ∃ c : Bool, (∀ v ∈ T, color v = c) ∧ (∀ v, color v = c → v ∈ T ∪ endpoints M).", DescribeRole.Theorem),
            Node("heawood_parameters", "heawood parameters", "Exact declaration: theorem heawood_parameters : beta HeawoodParameters.graph 2 = 7 ∧ psiSq HeawoodParameters.graph = 7 ∧ Omega HeawoodParameters.graph = 7 ∧ SF HeawoodParameters.graph 2 = 8.", DescribeRole.Theorem),
